<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap/app.php';
$user=pf_require_advertiser($pdo);$error='';
$placements=$pdo->query("SELECT placement_key,label,price_per_day,currency,min_duration_days,max_duration_days FROM pf_ad_placements WHERE surface='MAIN_SITE' AND is_active=1 AND price_per_day>0 ORDER BY sort_order,label")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 pf_verify_csrf();$title=trim((string)($_POST['title']??''));$summary=trim((string)($_POST['summary']??''));$url=trim((string)($_POST['url']??''));$placement=(string)($_POST['placement']??'');$start=(string)($_POST['start_date']??'');$end=(string)($_POST['end_date']??'');$parts=parse_url($url);$valid=static fn(string $d):bool=>preg_match('/\A\d{4}-\d{2}-\d{2}\z/',$d)===1&&date('Y-m-d',strtotime($d))===$d;
 $selected=null;foreach($placements as $p)if($p['placement_key']===$placement){$selected=$p;break;}
 if($title===''||strlen($title)>180||$summary===''||strlen($summary)>500||!filter_var($url,FILTER_VALIDATE_URL)||strtolower((string)($parts['scheme']??''))!=='https'||empty($parts['host'])||!$selected||!$valid($start)||!$valid($end)||$start<date('Y-m-d')||$end<$start)$error='Check the title, message, HTTPS destination, placement and campaign dates.';
 else{$days=(int)(new DateTimeImmutable($start))->diff(new DateTimeImmutable($end))->days+1;if($days<(int)$selected['min_duration_days']||$days>(int)$selected['max_duration_days'])$error='The selected placement does not support this campaign duration.';
  else{$budget=round((float)$selected['price_per_day']*$days,2);if($budget<=0)$error='This placement has not been priced yet.';else try{
   $pdo->beginTransaction();$slug=strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','-',$title),'-')).'-'.bin2hex(random_bytes(4));$starts=$start.' 00:00:00';$ends=$end.' 23:59:59';
   $q=$pdo->prepare("INSERT INTO pf_campaigns(advertiser_id,campaign_type,title,slug,summary,description,destination_url,reward_per_completion,total_quantity,approved_quantity,reserved_budget,spent_budget,currency,evidence_required,starts_at,ends_at,status) VALUES (?,'SITE_DISPLAY',?,?,?,?,?,0,0,0,0,0,?,0,?,?,'DRAFT')");
   $q->execute([(int)$user['id'],$title,$slug,$summary,$summary,$url,$selected['currency'],$starts,$ends]);$id=(int)$pdo->lastInsertId();$creative=['title'=>$title,'summary'=>$summary,'url'=>$url,'image'=>''];
   $pdo->prepare("INSERT INTO pf_site_campaigns(campaign_id,placement_key,requested_budget,creative_json,starts_at,ends_at,status) VALUES (?,?,?,?,?,?,'PENDING')")->execute([$id,$placement,$budget,json_encode($creative,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES),$starts,$ends]);
   $pdo->commit();header('Location: fund-site-campaign.php?id='.$id);exit;
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('PoketFlow site campaign creation failed: '.$e->getMessage());$error='The campaign could not be saved. Please try again.';}}
 }
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create main-site ad | PoketFlow</title><link rel="stylesheet" href="assets/marketplace.css"><style>.stack{display:grid;gap:10px}.stack input,.stack select,.stack textarea{width:100%;padding:12px;border:1px solid var(--line);border-radius:12px;font:inherit}</style></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">P</span><span>Poket<span>Flow</span></span></a><nav><a href="dashboard.php">Dashboard</a><a href="campaigns.php">Campaigns</a><a href="blog-campaigns.php">Blog ads</a><a href="wallet.php">Wallet</a></nav></header>
<main class="container"><section class="welcome"><p class="eyebrow">MAIN-SITE ADVERTISING</p><h1>Create a campaign</h1><p class="muted">The price is calculated from the administrator-configured daily rate and campaign duration.</p></section><?php if($error):?><div class="alert"><?=pf_e($error)?></div><?php endif;?><section class="panel"><?php if(!$placements):?><p class="muted">No main-site placements are currently available. Placement options will appear after pricing and inventory are configured.</p><?php else:?><form class="stack" method="post"><input type="hidden" name="_token" value="<?=pf_e(pf_csrf_token())?>"><label>Ad / business title</label><input name="title" maxlength="180" required><label>Short message</label><textarea name="summary" maxlength="500" rows="3" required></textarea><label>HTTPS destination URL</label><input name="url" type="url" placeholder="https://example.com" required><label>Placement</label><select name="placement" required><?php foreach($placements as $p):?><option value="<?=pf_e($p['placement_key'])?>"><?=pf_e($p['label'])?> — <?=pf_e($p['currency'])?> <?=number_format((float)$p['price_per_day'],2)?> per day</option><?php endforeach;?></select><label>Start date</label><input name="start_date" type="date" min="<?=date('Y-m-d')?>" required><label>End date</label><input name="end_date" type="date" min="<?=date('Y-m-d')?>" required><p class="small muted">All campaigns are reviewed before publication. No impression volume is guaranteed. Gambling, adult content, casinos and alcohol are prohibited.</p><button class="button primary" type="submit">Save campaign and review budget</button></form><?php endif;?></section></main></body></html>
